package it.andreademartini.trading.backtest.rebound;

import it.andreademartini.trading.backtest.*;
import it.andreademartini.trading.backtest.patternv1.PatternV1Commission;
import it.andreademartini.trading.backtest.patternv2.*;
import it.andreademartini.trading.backtest.weeklytte.WeeklyTteStore;
import it.andreademartini.trading.marketdata.*;
import it.andreademartini.trading.risk.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.*;
import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class TrendReboundEngineTest {
    @TempDir Path temp;
    static final LocalDate FIRST=LocalDate.of(2024,1,2);
    static LocalDate day(int index){var d=FIRST;for(int i=0;i<index;i++)d=TrendReboundEngine.nextSession(d);return d;}
    static TrendReboundConfiguration config(Object... changes){ObjectNode n=TrendReboundStore.JSON.valueToTree(TrendReboundConfiguration.defaults());n.put("startDate",day(8).toString());n.put("endDate",day(17).toString());n.set("symbols",TrendReboundStore.JSON.valueToTree(List.of("TEST")));n.put("trendSmaPeriod",8);n.put("recoverySmaPeriod",3);n.put("atrPeriod",3);n.put("slippagePercentPerSide",0);n.set("commission",TrendReboundStore.JSON.valueToTree(PatternV1Commission.fixed(BigDecimal.ZERO)));n.set("splitCosts",TrendReboundStore.JSON.valueToTree(new PatternV2SplitCosts(List.of())));for(int i=0;i<changes.length;i+=2)n.set(changes[i].toString(),TrendReboundStore.JSON.valueToTree(changes[i+1]));return TrendReboundStore.JSON.convertValue(n,TrendReboundConfiguration.class);}
    static HistoricalBar bar(String symbol,int index,double open,double high,double low,double close){return new HistoricalBar(symbol,day(index).atTime(16,0),BigDecimal.valueOf(open),BigDecimal.valueOf(high),BigDecimal.valueOf(low),BigDecimal.valueOf(close),1000,BarInterval.DAILY,"TEST",PriceAdjustment.ADJUSTED);}
    static List<HistoricalBar> series(String symbol){double[] closes={90,91,92,93,94,95,110,109,108,107,106,105,104,103,102,101,100,99};var bars=new ArrayList<HistoricalBar>();for(int i=0;i<closes.length;i++){double close=closes[i];bars.add(bar(symbol,i,close+0.5,close+1,close-1,close));}return bars;}
    static TrendReboundEngine engine(){return new TrendReboundEngine(new PositionSizingService(new TradePricingService()));}
    static TrendReboundRun simulate(TrendReboundConfiguration c,Map<String,List<HistoricalBar>> input){return engine().simulate(c,input,PatternV2Dataset.capture(input).id(),WeeklyTteStore.hash(c));}
    static TrendReboundRun run(Object... changes){return simulate(config(changes),Map.of("TEST",series("TEST")));}
    @Test void detectsFourDecliningClosesAndEntersOnlyOnFollowingOpen(){var r=run();var a=r.signals().getFirst();assertEquals(day(9),a.signalDate);assertEquals(List.of(110.0,109.0,108.0,107.0),a.closes);var t=r.trades().getFirst();assertEquals(day(10),t.entryDate());assertEquals(106.5,t.entryBasePrice());assertEquals(t.entryExecutionPrice()-1.5*t.atrAtSignal(),t.initialStop(),1e-10);}
    @Test void decliningCandlesAreNotASubstituteForDecliningCloses(){var bars=series("TEST");bars.set(8,bar("TEST",8,111,112,109,110));bars.set(9,bar("TEST",9,112,113,110,111));var r=simulate(config("endDate",day(9)),Map.of("TEST",bars));assertTrue(r.signals().isEmpty());}
    @Test void atrUsesGapTrueRangesAndWilderSeedAfterNPlusOneBars(){var state=new TrendReboundIndicators(config("atrPeriod",3));var a=state.onBar(bar("TEST",0,100,101,99,100));assertNull(a.atr());assertNull(state.onBar(bar("TEST",1,110,111,109,110)).atr());assertNull(state.onBar(bar("TEST",2,109,110,108,109)).atr());var value=state.onBar(bar("TEST",3,112,113,111,112));assertEquals(17.0/3,value.atr(),1e-12);var next=state.onBar(bar("TEST",4,113,114,112,113));assertEquals(((17.0/3)*2+2)/3,next.atr(),1e-12);}
    @Test void stopCanExecuteDuringEntrySession(){var bars=series("TEST");bars.set(10,bar("TEST",10,106.5,108,95,106));var r=simulate(config(),Map.of("TEST",bars));var t=r.trades().getFirst();assertEquals(t.entryDate(),t.exitDate());assertEquals(1,t.holdingBars());assertEquals("STOP",t.exitReason());assertEquals(t.initialStop(),t.exitBasePrice());}
    @Test void entrySlippageCanPutTheStopAboveTheRawOpeningPrice(){var r=run("slippagePercentPerSide",8.0);var t=r.trades().getFirst();assertEquals(t.entryDate(),t.exitDate());assertEquals("GAP_STOP",t.exitReason());assertEquals(t.entryBasePrice(),t.exitBasePrice());}
    @Test void gapStopExecutesAtOpenWithSellSlippageOnce(){var bars=series("TEST");bars.set(11,bar("TEST",11,90,91,89,90));var r=simulate(config("slippagePercentPerSide",0.03),Map.of("TEST",bars));var t=r.trades().getFirst();assertEquals("GAP_STOP",t.exitReason());assertEquals(90,t.exitBasePrice());assertEquals(90*(1-0.0003),t.exitExecutionPrice(),1e-10);}
    @Test void recoveryOnEntryCloseSchedulesNextOpenAndPrecedesLaterIntradayStop(){var bars=series("TEST");bars.set(10,bar("TEST",10,106.5,113,106,112));bars.set(11,bar("TEST",11,111,112,90,100));var r=simulate(config(),Map.of("TEST",bars));var t=r.trades().getFirst();assertEquals(day(10),t.recoverySignalDate());assertEquals(day(11),t.exitDate());assertEquals(111,t.exitBasePrice());assertEquals("RECOVERY",t.exitReason());assertEquals(2,t.holdingBars());assertEquals(1,r.trades().stream().filter(x->x.signalDate().equals(day(9))).count());}
    @Test void openingGapWinsReasonTieWithScheduledRecoveryAndExitsOnlyOnce(){var bars=series("TEST");bars.set(10,bar("TEST",10,106.5,113,106,112));bars.set(11,bar("TEST",11,90,113,89,112));var t=simulate(config(),Map.of("TEST",bars)).trades().getFirst();assertEquals("GAP_STOP",t.exitReason());assertEquals(day(10),t.recoverySignalDate());assertEquals(90,t.exitBasePrice());}
    @Test void fifthSessionClosesAtCloseIncludingEntryAsOne(){var t=run("stopAtrMultiplier",5).trades().getFirst();assertEquals(day(10),t.entryDate());assertEquals(day(14),t.exitDate());assertEquals(5,t.holdingBars());assertEquals("TIMEOUT",t.exitReason());assertEquals(102,t.exitBasePrice());}
    @Test void intradayStopPrecedesTimeoutOnFifthSession(){var bars=series("TEST");bars.set(14,bar("TEST",14,102,103,80,102));var t=simulate(config("stopAtrMultiplier",5),Map.of("TEST",bars)).trades().getFirst();assertEquals(day(14),t.exitDate());assertEquals("STOP",t.exitReason());assertEquals(5,t.holdingBars());}
    @Test void datasetEndDoesNotFabricateAClosedTradeOrPendingEntry(){var r=run("endDate",day(10),"stopAtrMultiplier",5);assertNull(r.trades().getFirst().exitDate());assertNull(r.trades().getFirst().netPnL());assertNotNull(r.trades().getFirst().unrealizedNetPnL());var signal=run("endDate",day(9));assertEquals("CENSORED",signal.signals().getFirst().status);assertTrue(signal.trades().isEmpty());}
    @Test void insufficientCashIsRecordedAndNeverDeferred(){var r=run("initialCapital",1,"commission",PatternV1Commission.fixed(BigDecimal.ONE));assertTrue(r.trades().isEmpty());assertTrue(r.signals().stream().anyMatch(a->"INSUFFICIENT_CAPITAL_OR_RISK_BUDGET".equals(a.reason)));assertTrue(r.signals().stream().noneMatch(a->a.entryDate!=null&&!a.entryDate.equals(a.plannedEntryDate)));}
    @Test void simultaneousSignalsUseAlphabeticalPriorityAndRespectExposure(){var c=config("symbols",List.of("ZZZ","AAA"),"initialCapital",1000,"riskPercent",100,"maxPositionValuePercent",100,"maxExposurePercent",100,"stopAtrMultiplier",5);var r=simulate(c,Map.of("ZZZ",series("ZZZ"),"AAA",series("AAA")));assertEquals("AAA",r.trades().getFirst().symbol());assertTrue(r.signals().stream().anyMatch(a->a.symbol.equals("ZZZ")&&"INSUFFICIENT_CAPITAL_OR_RISK_BUDGET".equals(a.reason)));assertTrue(r.equity().stream().allMatch(e->e.cash()>=-1e-9&&e.exposurePercent()<=100+1e-9));}
    static List<HistoricalBar> shifted(){var result=new ArrayList<HistoricalBar>();result.add(bar("BBB",0,89.5,90,88,89));for(var b:series("BBB")){int i=result.size();if(i>=18)break;result.add(bar("BBB",i,b.open(),b.high(),b.low(),b.close()));}return result;}
    @Test void intradayProceedsCannotFundAnotherOpeningEntry(){var aaa=series("AAA");aaa.set(11,bar("AAA",11,106,107,80,105));var c=config("symbols",List.of("AAA","BBB"),"initialCapital",1000,"riskPercent",100,"maxPositionValuePercent",100);var r=simulate(c,Map.of("AAA",aaa,"BBB",shifted()));var b=r.signals().stream().filter(a->a.symbol.equals("BBB")&&a.signalDate.equals(day(10))).findFirst().orElseThrow();assertEquals("INSUFFICIENT_CAPITAL_OR_RISK_BUDGET",b.reason);assertEquals(day(11),r.trades().getFirst().exitDate());}
    @Test void openingRecoveryProceedsCanFundAnotherOpeningEntry(){var aaa=series("AAA");aaa.set(10,bar("AAA",10,106.5,113,106,112));aaa.set(11,bar("AAA",11,111,112,110,111));var c=config("symbols",List.of("AAA","BBB"),"initialCapital",1000,"riskPercent",100,"maxPositionValuePercent",100);var r=simulate(c,Map.of("AAA",aaa,"BBB",shifted()));assertTrue(r.trades().stream().anyMatch(t->t.symbol().equals("BBB")&&t.entryDate().equals(day(11))));}
    @Test void missingNextSessionExpiresEntryAndResetsWarmup(){var bars=series("TEST");bars.remove(10);var r=simulate(config(),Map.of("TEST",bars));assertEquals("MISSING_NEXT_OPEN",r.signals().getFirst().reason);assertTrue(r.trades().isEmpty());assertTrue(r.dataQuality().stream().anyMatch(i->i.code().equals("MISSING_SESSIONS")));}
    @Test void missingPositionBarIsCensoredInsteadOfInventingAnExit(){var bars=series("TEST");bars.remove(11);var r=simulate(config(),Map.of("TEST",bars));var t=r.trades().getFirst();assertNull(t.exitDate());assertEquals("DATA_GAP_UNRESOLVED",t.dataStatus());assertTrue(r.equity().stream().anyMatch(TrendReboundRun.Equity::dataIncomplete));}
    @Test void costsAndOpenMarkToMarketReconcileWithoutSubtractingSlippageTwice(){for(var end:List.of(day(10),day(17))){var r=run("endDate",end,"commission",PatternV1Commission.fixed(BigDecimal.ONE),"slippagePercentPerSide",0.03);var recon=(Map<?,?>)r.analysis().get("reconciliation");assertEquals(true,recon.get("passed"));var t=r.trades().getFirst();if(t.exitDate()!=null)assertEquals((t.exitExecutionPrice()-t.entryExecutionPrice())*t.quantity()-t.entryCommission()-t.exitCommission(),t.netPnL(),1e-9);assertTrue(t.slippageCosts()>0);assertTrue(t.sizingRiskWithCosts()<=10000*0.5/100+1e-9);}}
    @Test void fullDefaultWarmupUses200CompletedClosesAndNoFutureValues(){var bars=new ArrayList<HistoricalBar>();for(int i=0;i<210;i++){double close=90+i*0.1;bars.add(bar("TEST",i,close,close+1,close-1,close));}for(double close:new double[]{140,139,138,137}){int i=bars.size();bars.add(bar("TEST",i,close,close+1,close-1,close));}var c=config("trendSmaPeriod",200,"recoverySmaPeriod",5,"atrPeriod",14,"startDate",day(200),"endDate",day(213));var r=simulate(c,Map.of("TEST",bars));assertEquals(day(213),r.signals().getFirst().signalDate);assertEquals(List.of(140.0,139.0,138.0,137.0),r.signals().getFirst().closes);assertEquals(day(200),r.equity().getFirst().date());var prefix=simulate(config("endDate",day(9)),Map.of("TEST",series("TEST")));var full=run();assertEquals(prefix.signals().getFirst().atr,full.signals().getFirst().atr);assertEquals(prefix.signals().getFirst().trendSma,full.signals().getFirst().trendSma);}
    @Test void persistedSnapshotReplayIsEconomicallyIdenticalAndExcelContainsAudits()throws Exception{var store=new TrendReboundStore(temp);var service=new TrendReboundService(store,new BacktestEngine(null),engine());var c=config();var original=service.onSnapshot(c,PatternV2Dataset.capture(Map.of("TEST",series("TEST"))));var replay=service.replay(original.runId());assertEquals(original.trades(),replay.trades());assertEquals(original.equity(),replay.equity());assertEquals(2,store.history().size());try(var wb=new XSSFWorkbook(new ByteArrayInputStream(new TrendReboundExcelExporter().export(original)))){for(String sheet:List.of("DASHBOARD","CONFIGURATION","SIGNALS","TRADES","OPEN_POSITIONS","EQUITY","ANNUAL_RESULTS","DATA_QUALITY","RECONCILIATION"))assertNotNull(wb.getSheet(sheet));assertEquals(original.trades().stream().filter(t->t.exitDate()!=null).count()+1,wb.getSheet("TRADES").getPhysicalNumberOfRows());assertTrue(wb.getSheet("SIGNALS").getRow(0).cellIterator().hasNext());}}
    @Test void adjustedSplitCommissionBasisIsReused(){var bars=series("TEST");var costs=new PatternV2SplitCosts(List.of(new PatternV2SplitCosts.Rule("TEST",PatternV2SplitCosts.Basis.SPLIT_ADJUSTED,day(0),day(17),List.of(new PatternV2SplitCosts.Split(day(15),BigDecimal.valueOf(4))))));var r=simulate(config("splitCosts",costs,"commission",PatternV1Commission.ibkr()),Map.of("TEST",bars));assertEquals(4,r.trades().getFirst().splitFactor());assertEquals(PatternV2SplitCosts.commission(PatternV1Commission.ibkr(),BigDecimal.valueOf(4)).charge(r.trades().getFirst().quantity(),BigDecimal.valueOf(r.trades().getFirst().entryExecutionPrice())).doubleValue(),r.trades().getFirst().entryCommission());}
    @Test void invalidInitialStopRejectsAnOtherwiseValidCandidate(){var r=run("stopAtrMultiplier",100);assertTrue(r.trades().isEmpty());assertTrue(r.signals().stream().allMatch(a->a.reason.equals("INVALID_STOP")||a.status.equals("CENSORED")));}
    @Test void rawPricesCrossingKnownSplitAreExcludedWithAnExplicitReason(){var raw=series("TEST").stream().map(b->new HistoricalBar("TEST",b.dateTime(),b.getOpen(),b.getHigh(),b.getLow(),b.getClose(),b.volume(),b.interval(),b.provider(),PriceAdjustment.RAW)).toList();var costs=new PatternV2SplitCosts(List.of(new PatternV2SplitCosts.Rule("TEST",PatternV2SplitCosts.Basis.RAW,day(0),day(17),List.of(new PatternV2SplitCosts.Split(day(15),BigDecimal.valueOf(4))))));var r=simulate(config("symbols",List.of("TEST","OTHER"),"splitCosts",costs),Map.of("TEST",raw,"OTHER",series("OTHER")));assertTrue(r.dataQuality().stream().anyMatch(i->i.symbol().equals("TEST")&&i.code().equals("EXCLUDED_INVALID_DATA")));assertTrue(r.trades().stream().noneMatch(t->t.symbol().equals("TEST")));}
}
